for (let i = 0; i < n; i++) {
  positions[input[i + 1]].push(i);
}

const values = [];
for (let v = 1; v <= n; v++) {
  if (positions[v].length > 0) values.push(v);
}

let answer = 1;

for (let x = 0; x < values.length; x++) {
  for (let y = x + 1; y < values.length; y++) {
    const a = positions[values[x]];
    const b = positions[values[y]];
    let i = 0;
    let j = 0;
    let previous = -1;
    let runs = 0;

    while (i < a.length || j < b.length) {
      let current;
      if (j >= b.length || (i < a.length && a[i] < b[j])) {
        current = 0;
        i++;
      } else {
        current = 1;
        j++;
      }

      if (current !== previous) {
        runs++;
        previous = current;
      }
    }

    if (runs > answer) answer = runs;
  }
}

